code.formula:
@Command([EditDocument];"1");

@If(Category = ""; @Return(@Do(@Command([EditGotoField];"Category") ;@Prompt([Ok];"Missing Value"; "Please select the Category!")));"");
@If(Send = ""; @Return(@Do(@Command([EditGotoField];"Send") ;@Prompt([Ok];"Missing Value"; "Please select the Recipients before proceeding!")));"");
@If(Subject = ""; @Return(@Do(@Command([EditGotoField];"Subject") ;@Prompt([Ok];"Missing Value"; "Please state the Subject before proceeding!")));"");

FIELD DateSent :=@Today;
FIELD CurrentAction := "Submitted";

@MailSend(Send;NULL;NULL;Title +" Info Updates - "+Subject;"";"Please follow this document link  --->  ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

